export var setSelectedRegion = function(selReg) {
  var deltaSum, endIdx, endIdxSpace, isDelta, maxIdx, startIdx, startIdxSpace;
  log("setSelectedRegion");
  if (!((selReg != null) || (selection != null))) {
    return;
  }
  ({startIdx, endIdx, isDelta} = selReg);
  if ((selection == null) && isDelta) {
    throw new Error("Cannot apply delta on empty selection!");
  }
  if (selection == null) {
    selection = selReg;
  } else if (!isDelta && selection.startIdx === startIdx && selection.endIdx === endIdx) { //# nothing to update
    return;
  } else if (!isDelta) { // at least one new value to set
    if (startIdx != null) {
      selection.startIdx = startIdx;
    }
    if (endIdx != null) {
      selection.endIdx = endIdx; // apply delta
    }
  } else {
    if (startIdx != null) {
      selection.startIdx += startIdx;
    }
    if (endIdx != null) {
      selection.endIdx += endIdx;
    }
  }
  //# Readjust invald configurations
  maxIdx = xAxisData.length - 1;
  // olog { selReg, selection }

  // first radically cut down to the limits
  if (selection.endIdx > maxIdx) {
    selection.endIdx = maxIdx;
  }
  if (selection.startIdx < 0) {
    selection.startIdx = 0;
  }
  // Then resolve potential impossibilities
  if (selection.startIdx >= selection.endIdx && selection.endIdx === maxIdx) {
    // obvious choice when endIdx is at the max
    selection.startIdx = selection.endIdx - 1;
  }
  if (selection.endIdx <= selection.startIdx && selection.startIdx === 0) {
    // obvious choice when startIdx is at 0W
    selection.endIdx = selection.startIdx + 1;
  }
  if (selection.startIdx >= selection.endIdx) { // either decrease startIdx or increase endIdx
    if (isDelta) {
      deltaSum = 0;
      if (startIdx != null) {
        deltaSum += startIdx;
      }
      if (endIdx != null) {
        deltaSum += endIdx;
      }
      // increase endIdx, when we were moving up - unless we are already at the max
      if (deltaSum > 0 && selection.endIdx < maxIdx) {
        selection.endIdx++;
      } else if (deltaSum > 0 && selection.endIdx === maxIdx) {
        selection.startIdx--;
      }
      // decrease startIdx, when we were moving down - unless we are at 0
      if (deltaSum < 0 && selection.startIdx > 0) {
        selection.startIdx--;
      } else if (deltaSum < 0 && selection.startIdx === 0) {
        selection.endIdx++;
      }
      // in case of zero - default to decrease startIdx - unless we are at 0
      if (deltaSum === 0 && selection.startIdx > 0) {
        selection.startIdx--;
      } else if (deltaSum === 0 && selection.startIdx === 0) {
        selection.endIdx++;
      }
    } else {
      // The index that has more space to move moves
      startIdxSpace = selection.startIdx;
      endIdxSpace = maxIdx - selection.endIdx;
      if (endIdxSpace > startIdxSpace) {
        selection.endIdx++;
      }
      if (startIdxSpace > endIdxSpace) {
        selection.startIdx--;
      }
      if (endIdxSpace === startIdxSpace) {
        selection.startIdx--;
      }
    }
  }
  if (selection.startIdx < 0 || selection.endIdx > maxIdx || selection.endIdx <= selection.startIdx) {
    console.error("Adjusting indices went wrong!");
    olog(selection);
  }
  if (onRangeSelect != null) {
    //# communicate change and redraw 
    onRangeSelect(selection);
  }
  redrawChart();
};

